// ?clear@Rva008A30C0Owner@@QAEXXZ
// partial score=0.79 date=2026-09-16
// cl: /DNDEBUG /MD
// Retail RVA 0x008A30C0. Pops every entry off the array at +8, clearing one
// flag bit when the entry carries any of a mask and releasing it through
// vtable slot two otherwise. Nothing names the owner, so both classes are
// address-derived.

class Rva008A30C0Item
{
public:
	virtual void slot0();
	virtual void slot1();
	virtual void release();

	unsigned int m_bfmeFlags;
};

class Rva008A30C0Owner
{
public:
	void clear();

	unsigned char m_bfmePad000[ 4 ];
	int m_bfmeCount;
	Rva008A30C0Item **m_bfmeItems;
};

void Rva008A30C0Owner::clear()
{
	for( ;; )
	{
		int remaining = m_bfmeCount;

		if( remaining == 0 )
			break;

		do
		{
			Rva008A30C0Item *item = m_bfmeItems[ --m_bfmeCount ];

			if( ( item->m_bfmeFlags & 0x0fff0000 ) > 0 )
				item->m_bfmeFlags &= 0xbfffffff;
			else
				item->release();
		}
		while( --remaining != 0 );
	}
}
